CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY, username text UNIQUE NOT NULL, display_name text NOT NULL, password_hash text NOT NULL, bio text DEFAULT '', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS posts (id uuid PRIMARY KEY, author_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, body text NOT NULL, community text, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS likes (user_id uuid REFERENCES users(id) ON DELETE CASCADE, post_id uuid REFERENCES posts(id) ON DELETE CASCADE, PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS comments (id uuid PRIMARY KEY, post_id uuid REFERENCES posts(id) ON DELETE CASCADE, author_id uuid REFERENCES users(id) ON DELETE CASCADE, parent_id uuid REFERENCES comments(id) ON DELETE CASCADE, body text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS follows (follower_id uuid REFERENCES users(id) ON DELETE CASCADE, following_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(follower_id,following_id), CHECK(follower_id <> following_id));
CREATE TABLE IF NOT EXISTS communities (id uuid PRIMARY KEY, slug text UNIQUE NOT NULL, name text NOT NULL, description text DEFAULT '', owner_id uuid REFERENCES users(id), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS community_members (community_id uuid REFERENCES communities(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(community_id,user_id));
CREATE TABLE IF NOT EXISTS bookmarks (user_id uuid REFERENCES users(id) ON DELETE CASCADE, post_id uuid REFERENCES posts(id) ON DELETE CASCADE, PRIMARY KEY(user_id,post_id));
CREATE TABLE IF NOT EXISTS discussions (id uuid PRIMARY KEY, author_id uuid REFERENCES users(id), topic text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS positions (discussion_id uuid REFERENCES discussions(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, stance text CHECK(stance IN ('FOR','AGAINST','UNDECIDED')) NOT NULL, changed_at timestamptz DEFAULT now(), PRIMARY KEY(discussion_id,user_id));
CREATE TABLE IF NOT EXISTS arguments (id uuid PRIMARY KEY, discussion_id uuid REFERENCES discussions(id) ON DELETE CASCADE, author_id uuid REFERENCES users(id), stance text CHECK(stance IN ('FOR','AGAINST')) NOT NULL, body text NOT NULL, parent_id uuid REFERENCES arguments(id), created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY, user_id uuid REFERENCES users(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id), type text NOT NULL, body text NOT NULL, read_at timestamptz, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS conversations (id uuid PRIMARY KEY, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS conversation_members (conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, last_read_at timestamptz, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE IF NOT EXISTS messages (id uuid PRIMARY KEY, conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid REFERENCES users(id) ON DELETE CASCADE, body text NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS reports (id uuid PRIMARY KEY, reporter_id uuid REFERENCES users(id), target_type text NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, status text DEFAULT 'OPEN', created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS blocks (blocker_id uuid REFERENCES users(id) ON DELETE CASCADE, blocked_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(blocker_id,blocked_id));
CREATE TABLE IF NOT EXISTS mutes (muter_id uuid REFERENCES users(id) ON DELETE CASCADE, muted_id uuid REFERENCES users(id) ON DELETE CASCADE, PRIMARY KEY(muter_id,muted_id));
